param([int]$Port=8080)
$root=(Get-Location).Path;$keyId=$env:RAZORPAY_KEY_ID;if(-not $keyId){$keyId='rzp_test_TtJPF8vMvv7w5w'};$keySecret=$env:RAZORPAY_KEY_SECRET
$presence=@{};$listener=[Net.Sockets.TcpListener]::new([Net.IPAddress]::Any,$Port);$listener.Start();Write-Host "BattleHub: http://localhost:$Port  |  LAN ready"
while($true){$client=$listener.AcceptTcpClient();$stream=$client.GetStream();$reader=New-Object IO.StreamReader($stream,[Text.Encoding]::ASCII,$false,4096,$true)
$request=$reader.ReadLine();$headers=@{};if(-not $request){$client.Close();continue};while($line=$reader.ReadLine()){if([string]::IsNullOrWhiteSpace($line)){break};$parts=$line.Split(':',2);if($parts.Count-eq 2){$headers[$parts[0].Trim().ToLower()]=$parts[1].Trim()}}
$parts=$request.Split(' ');$method=$parts[0];$uri=$parts[1];$relative=[Uri]::UnescapeDataString(([Uri]("http://local$uri")).AbsolutePath.TrimStart('/'));$status='200 OK';$type='text/plain';
try{if($method-eq 'POST' -and $relative-eq 'api/presence'){$length=[int]$headers['content-length'];$chars=New-Object char[] $length;for($i=0;$i-lt $length;$i++){$chars[$i]=$reader.Read()};$player=($chars -join '')|ConvertFrom-Json;if($player.id){$presence[$player.id]=[DateTimeOffset]::UtcNow.ToUnixTimeSeconds()};$now=[DateTimeOffset]::UtcNow.ToUnixTimeSeconds();$online=@($presence.Keys|Where-Object{$now-[long]$presence[$_] -lt 75}).Count;$bytes=[Text.Encoding]::UTF8.GetBytes('{"online":'+$online+'}');$type='application/json'
}elseif($method-eq 'GET' -and $relative-eq 'api/presence'){ $now=[DateTimeOffset]::UtcNow.ToUnixTimeSeconds();$online=@($presence.Keys|Where-Object{$now-[long]$presence[$_] -lt 75}).Count;$bytes=[Text.Encoding]::UTF8.GetBytes('{"online":'+$online+'}');$type='application/json'
}elseif($method-eq 'POST' -and $relative-eq 'api/config'){$bytes=[Text.Encoding]::UTF8.GetBytes('{"keyId":"'+$keyId+'"}');$type='application/json'
}elseif($method-eq 'POST' -and $relative-eq 'api/order'){if(-not $keySecret){throw 'RAZORPAY_KEY_SECRET is not configured'};$length=[int]$headers['content-length'];$chars=New-Object char[] $length;for($i=0;$i-lt $length;$i++){$chars[$i]=$reader.Read()};$body=($chars -join '')|ConvertFrom-Json;$amount=[math]::Max(5,[int]$body.amount)*100;$auth=[Convert]::ToBase64String([Text.Encoding]::ASCII.GetBytes("$keyId`:$keySecret"));$payload=@{amount=$amount;currency='INR';receipt="bh$(Get-Date -Format yyyyMMddHHmmss)"}|ConvertTo-Json;$order=Invoke-RestMethod -Method Post -Uri 'https://api.razorpay.com/v1/orders' -Headers @{Authorization="Basic $auth";Accept='application/json'} -ContentType 'application/json' -Body $payload;$bytes=[Text.Encoding]::UTF8.GetBytes('{"orderId":"'+$order.id+'","amount":'+$amount+'}');$type='application/json'
}elseif($method-eq 'POST' -and $relative-eq 'api/verify'){if(-not $keySecret){throw 'RAZORPAY_KEY_SECRET is not configured'};$length=[int]$headers['content-length'];$chars=New-Object char[] $length;for($i=0;$i-lt $length;$i++){$chars[$i]=$reader.Read()};$body=($chars -join '')|ConvertFrom-Json;$hmac=New-Object Security.Cryptography.HMACSHA256;$hmac.Key=[Text.Encoding]::UTF8.GetBytes($keySecret);$payload="$($body.razorpay_order_id)|$($body.razorpay_payment_id)";$expected=[BitConverter]::ToString($hmac.ComputeHash([Text.Encoding]::UTF8.GetBytes($payload))).Replace('-','').ToLower();$bytes=[Text.Encoding]::UTF8.GetBytes('{"verified":'+([bool]($expected-eq $body.razorpay_signature)).ToString().ToLower()+'}');$type='application/json'
}else{if([string]::IsNullOrWhiteSpace($relative)){$relative='index.html'};$file=Join-Path $root (($relative -replace '/','\'));if(-not(Test-Path -LiteralPath $file -PathType Leaf)){$status='404 Not Found';$bytes=[Text.Encoding]::UTF8.GetBytes('Not found')}else{$bytes=[IO.File]::ReadAllBytes($file);switch([IO.Path]::GetExtension($file)){'.html'{$type='text/html'} '.css'{$type='text/css'} '.js'{$type='application/javascript'} '.json'{$type='application/json'}}}}}catch{$status='500 Internal Server Error';$bytes=[Text.Encoding]::UTF8.GetBytes('{"error":"'+$_.Exception.Message.Replace('"','')+'"}');$type='application/json'}
$head="HTTP/1.1 $status`r`nContent-Type: $type; charset=utf-8`r`nContent-Length: $($bytes.Length)`r`nAccess-Control-Allow-Origin: *`r`nCache-Control: no-store`r`nConnection: close`r`n`r`n";$headBytes=[Text.Encoding]::ASCII.GetBytes($head);$stream.Write($headBytes,0,$headBytes.Length);$stream.Write($bytes,0,$bytes.Length);$client.Close()}
